<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'caisse.rapport')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php'; require_once __DIR__ . '/_finance.php';
$db=Database::getInstance();$role=$user['role_system'];$date=(string)($_GET['date']??date('Y-m-d'));if(!financeValidDate($date))$date=date('Y-m-d');
$register=$db->fetch('SELECT date,initial,montant_in,montant_out,balance,status,opened_by,closed_by,closed_at FROM caisse WHERE date = ? LIMIT 1',[$date]);
$sales=$db->fetch("SELECT COUNT(*) AS count,COALESCE(SUM(total_amount),0) AS sales,COALESCE(SUM(netcash),0) AS netcash,COALESCE(SUM(tva),0) AS vat,COALESCE(SUM(tva_paid),0) AS vat_paid,COALESCE(SUM(debt),0) AS debt FROM sales WHERE status='Active' AND date = ?",[$date]);
$cashIn=(float)$db->fetchColumn('SELECT COALESCE(SUM(amount),0) FROM cash_in WHERE date_created = ?',[$date]);$cashOut=(float)$db->fetchColumn('SELECT COALESCE(SUM(amount),0) FROM cash_out WHERE created_at = ?',[$date]);$expense=(float)$db->fetchColumn("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE status='Active' AND date = ?",[$date]);
$debtStates=$db->fetchAll("SELECT status,COUNT(*) AS count,COALESCE(SUM(GREATEST(COALESCE(amount,0)-COALESCE(paid_amount,0),0)),0) AS balance FROM debts GROUP BY status ORDER BY status");
?>
<section class="space-y-5"><header><p class="text-sm font-semibold text-amber-800">Clôture & contrôle</p><h1 class="mt-1 text-2xl font-bold text-slate-900">États comptables</h1><p class="mt-1 text-sm text-slate-600">Situation journalière et soldes des créances.</p></header>
<form method="get" action="<?=financeEscape(app_url('router.php'))?>" class="flex flex-col gap-3 rounded-md border border-slate-200 bg-white p-4 sm:flex-row sm:items-end"><input type="hidden" name="route" value="<?=financeEscape($role.'/caisse/etats')?>"><label class="space-y-1 text-sm font-medium">Date de l’état<input type="date" name="date" value="<?=financeEscape($date)?>" class="block rounded-md border border-slate-300 px-3 py-2 font-normal"></label><button class="rounded-md bg-green-700 px-4 py-2 text-sm font-semibold text-white">Afficher l’état</button><a href="<?=financeEscape(app_route_url('caisse/rapports'))?>" class="px-3 py-2 text-sm font-medium text-green-800">Rapports mensuels</a></form>
<div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><?php foreach([['Ventes TTC',(float)$sales['sales'],'green'],['Net encaissé',(float)$sales['netcash'],'blue'],['TVA facturée',(float)$sales['vat'],'amber'],['TVA encaissée',(float)$sales['vat_paid'],'teal']] as [$label,$amount,$color]):?><article class="rounded-md border border-slate-200 bg-white p-5"><p class="text-sm text-slate-500"><?=financeEscape($label)?></p><p class="mt-2 text-xl font-bold text-<?=financeEscape($color)?>-800"><?=number_format($amount,0,',',' ')?> FBu</p></article><?php endforeach;?></div>
<div class="grid gap-5 xl:grid-cols-2"><section class="rounded-md border border-slate-200 bg-white p-5"><div class="flex items-center justify-between"><h2 class="font-semibold text-slate-900">État de caisse</h2><span class="rounded-full px-2.5 py-1 text-xs font-medium <?= $register ? ((int)$register['status']===0?'bg-green-100 text-green-800':'bg-slate-100 text-slate-700') : 'bg-amber-100 text-amber-800' ?>"><?= $register ? ((int)$register['status']===0?'Ouverte':'Fermée') : 'Non ouverte' ?></span></div><?php if($register):?><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><dt class="text-slate-500">Fond initial</dt><dd><?=number_format((float)$register['initial'],0,',',' ')?> FBu</dd></div><div class="flex justify-between"><dt class="text-slate-500">Entrées caisse</dt><dd class="text-green-800">+<?=number_format((float)$register['montant_in'],0,',',' ')?> FBu</dd></div><div class="flex justify-between"><dt class="text-slate-500">Sorties caisse</dt><dd class="text-rose-700">−<?=number_format((float)$register['montant_out'],0,',',' ')?> FBu</dd></div><div class="flex justify-between border-t pt-3 font-bold"><dt>Solde calculé</dt><dd><?=number_format((float)$register['balance'],0,',',' ')?> FBu</dd></div><div class="text-xs text-slate-500">Ouverte par <?=financeEscape($register['opened_by']?:'—')?> · Fermée par <?=financeEscape($register['closed_by']?:'—')?><?= $register['closed_at'] ? ' à '.financeEscape(date('d/m/Y H:i',strtotime($register['closed_at']))) : '' ?></div></dl><?php else:?><p class="mt-4 text-sm text-slate-500">Aucun état de caisse enregistré pour cette date.</p><?php endif;?></section>
<section class="rounded-md border border-slate-200 bg-white p-5"><h2 class="font-semibold text-slate-900">Récapitulatif du jour</h2><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><dt class="text-slate-500">Nombre de ventes</dt><dd class="font-semibold"><?=number_format((int)$sales['count'],0,',',' ')?></dd></div><div class="flex justify-between"><dt class="text-slate-500">Entrées manuelles</dt><dd class="text-green-800">+<?=number_format($cashIn,0,',',' ')?> FBu</dd></div><div class="flex justify-between"><dt class="text-slate-500">Sorties de caisse</dt><dd class="text-rose-700">−<?=number_format($cashOut,0,',',' ')?> FBu</dd></div><div class="flex justify-between"><dt class="text-slate-500">Dépenses actives</dt><dd class="text-rose-700">−<?=number_format($expense,0,',',' ')?> FBu</dd></div><div class="flex justify-between border-t pt-3"><dt class="font-semibold">Dettes créées</dt><dd class="font-semibold"><?=number_format((float)$sales['debt'],0,',',' ')?> FBu</dd></div></dl></section></div>
<section class="overflow-hidden rounded-md border border-slate-200 bg-white"><div class="border-b px-5 py-4"><h2 class="font-semibold">Situation des créances</h2><p class="mt-1 text-sm text-slate-500">Soldes restants, toutes dates confondues</p></div><div class="overflow-x-auto"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">État</th><th class="px-5 py-3 text-right">Dossiers</th><th class="px-5 py-3 text-right">Solde restant</th></tr></thead><tbody class="divide-y"><?php $debtLabels=[0=>'Impayée',1=>'Réglée',2=>'Partielle'];if(!$debtStates):?><tr><td colspan="3" class="px-5 py-8 text-center text-slate-500">Aucune créance.</td></tr><?php else:foreach($debtStates as $state):?><tr><td class="px-5 py-3"><?=financeEscape($debtLabels[(int)$state['status']]??'Autre')?></td><td class="px-5 py-3 text-right"><?=number_format((int)$state['count'],0,',',' ')?></td><td class="px-5 py-3 text-right font-semibold"><?=number_format((float)$state['balance'],0,',',' ')?> FBu</td></tr><?php endforeach;endif;?></tbody></table></div></section></section>